document.addEventListener('DOMContentLoaded',()=>{const heroSection=document.querySelector('.hero');if(!heroSection)return;const canvas=document.createElement('canvas');canvas.id='hero-particles';canvas.style.position='absolute';canvas.style.top='0';canvas.style.left='0';canvas.style.width='100%';canvas.style.height='100%';canvas.style.pointerEvents='none';canvas.style.zIndex='0';if(getComputedStyle(heroSection).position==='static'){heroSection.style.position='relative';}
heroSection.insertBefore(canvas,heroSection.firstChild);const ctx=canvas.getContext('2d');let width,height;let mouse={x:-1000,y:-1000};let isMouseActive=false;const config={particleCount:80,baseRadius:600,breathingSpeed:0.002,breathingRange:30,color:'rgba(60, 60, 60, 0.4)'};let particles=[];let time=0;function resize(){width=canvas.width=heroSection.offsetWidth;height=canvas.height=heroSection.offsetHeight;if(!isMouseActive){mouse.x=width/2;mouse.y=height/2;}
if(width<768){config.particleCount=40;config.baseRadius=300;}else{config.particleCount=80;config.baseRadius=600;}
initParticles();}
window.addEventListener('resize',resize);function updateMouse(x,y){const rect=canvas.getBoundingClientRect();mouse.x=x-rect.left;mouse.y=y-rect.top;isMouseActive=true;}
document.addEventListener('mousemove',e=>updateMouse(e.clientX,e.clientY));document.addEventListener('touchmove',e=>{if(e.touches.length>0){updateMouse(e.touches[0].clientX,e.touches[0].clientY);}});class Particle{constructor(){this.angle=Math.random()*Math.PI*2;this.radiusOffset=Math.random();this.speed=0.01+Math.random()*0.02;this.size=Math.random()*1.5+0.5;this.x=mouse.x;this.y=mouse.y;this.vx=0;this.vy=0;this.friction=0.92;this.ease=0.04+Math.random()*0.04;}
update(breathingOffset){const currentRadius=(config.baseRadius+breathingOffset)*this.radiusOffset;this.angle+=this.speed;const targetX=mouse.x+(Math.cos(this.angle)*currentRadius*1.5);const targetY=mouse.y+(Math.sin(this.angle)*currentRadius);this.x+=(targetX-this.x)*this.ease;this.y+=(targetY-this.y)*this.ease;}
draw(){ctx.fillStyle=config.color;ctx.beginPath();ctx.arc(this.x,this.y,this.size,0,Math.PI*2);ctx.fill();}}
function initParticles(){particles=[];for(let i=0;i<config.particleCount;i++){particles.push(new Particle());}}
function animate(){ctx.clearRect(0,0,width,height);time+=1;const breathingOffset=Math.sin(time*config.breathingSpeed*10)*config.breathingRange;particles.forEach(p=>{p.update(breathingOffset);p.draw();});requestAnimationFrame(animate);}
resize();animate();});